import sys; sys.path.insert(0,'/home/claude/honglifecalc/build')
from enrich_lib import build, table, add_top
P='/ru/usn-ip.html'

# Toggle: for USN "доходы минус расходы" the 1% contribution is counted from (доходы − расходы).
# Keep True only if confirmed on nalog.gov.ru (see claims_F5.json).
NET15=True

FIX=57390; MAX1=321818

form='''<form class="card" id="form" onsubmit="return false"><h2>Ваши данные</h2><label class="f"><span>Доходы за год, ₽</span><input id="i" inputmode="decimal" value="3 000 000"><small>Все поступления от бизнеса за 2026 год.</small></label><label class="f"><span>Расходы за год, ₽</span><input id="e" inputmode="decimal" value="1 500 000"><small>Подтверждённые расходы для УСН 15% (без страховых взносов ИП – калькулятор добавит их сам).</small></label><label class="chk"><input type="checkbox" id="emp"> Есть сотрудники (налог 6% можно уменьшить на взносы не больше чем на 50%)</label></form>'''

calc='''function calc(){const i=Math.max(0,num('i')),e=Math.min(i,Math.max(0,num('e'))),FIX=57390,MAX1=321818,NET15='''+('true' if NET15 else 'false')+''';
 const c=FIX+Math.min(MAX1,Math.max(0,i-300000)*.01),c15=FIX+Math.min(MAX1,Math.max(0,(NET15?i-e:i)-300000)*.01);
 const t6=Math.max($('emp').checked?i*.06/2:0,i*.06-c),t15=Math.max(i*.01,(i-e-c15)*.15),a=t6+c,b=t15+c15,best=a<=b?'6%':'15%';
 const nds=i>20000000,sh=x=>i?' ('+pc(x/i)+' дохода)':'';
 return big('Выгоднее: УСН '+best,rub(Math.min(a,b),0),'налог + взносы за год')+kv([['УСН 6%: взносы ИП',rub(c,0)],['УСН 6%: налог после уменьшения на взносы',rub(t6,0)],['УСН 6%: всего'+sh(a),rub(a,0),'t'],['УСН 15%: взносы ИП',rub(c15,0)],['УСН 15%: налог (не меньше 1% дохода)',rub(t15,0)],['УСН 15%: всего'+sh(b),rub(b,0),'t'],['Разница',rub(Math.abs(a-b),0),'pos'],['НДС',nds?'⚠ доход выше 20 млн ₽ – нужно платить НДС':'не платите (доход до 20 млн ₽)']])+'<p class="note">Для ИП без особых льгот, по базовым ставкам 6% и 15%. Регион может установить ставки ниже. Взносы: '+rub(FIX,0)+' фиксированные + 1% с дохода свыше 300 000 ₽ (не больше '+rub(MAX1,0)+').</p>'}'''

def tot(i,e,emp=False):
    c=FIX+min(MAX1,max(0,i-300000)*.01)
    c15=FIX+min(MAX1,max(0,((i-e) if NET15 else i)-300000)*.01)
    t6=max(i*.06/2 if emp else 0,i*.06-c); t15=max(i*.01,(i-e-c15)*.15)
    return c,t6,c+t6,c15,t15,c15+t15
r=lambda x:f"{round(x):,}".replace(',',' ')+' ₽'
rows=[]
for i,e in [(1200000,400000),(3000000,1500000),(6000000,4800000),(12000000,3000000)]:
    c,t6,a,c15,t15,b=tot(i,e)
    rows.append([r(i),r(e),r(a),r(b),'6%' if a<=b else '15%'])
print(rows)
d=tot(3000000,1500000); print([round(x) for x in d])
def be(i):
    lo,hi=0,i
    for _ in range(80):
        m=(lo+hi)/2;x=tot(i,m)
        if x[5]>x[2]: lo=m
        else: hi=m
    return m/i
bes=[(i,be(i)) for i in (3e6,6e6,10e6)]; print(bes)
emp=tot(1200000,400000,True); print([round(x) for x in emp])
pct=lambda x:f"{x*100:.0f}%"

fig=[['Фиксированные взносы ИП за 2026 год','57 390 ₽','Платят все ИП, даже без дохода. Срок – до 28 декабря 2026 года.'],
     ['Дополнительный взнос','1% с дохода свыше 300 000 ₽, не больше 321 818 ₽','Срок – до 1 июля 2027 года.'],
     ['Ставка УСН «Доходы»','6%','Регион может снизить до 1%.'],
     ['Ставка УСН «Доходы минус расходы»','15%','Регион может снизить до 5%.'],
     ['Минимальный налог на УСН 15%','1% от доходов','Платится, если обычный налог получился меньше.'],
     ['Уменьшение налога 6% на взносы','без сотрудников – полностью; с сотрудниками – не больше чем на 50%','Взносы вычитаются из налога, а не из дохода.'],
     ['НДС на УСН в 2026 году','платят ИП с доходом больше 20 млн ₽','Ставки 5% или 7% (специальные) либо 22% (общая). Порог: 15 млн ₽ в 2027 году, 10 млн ₽ с 2028 года.'],
     ['Сроки по УСН для ИП','авансы – до 28 апреля, 28 июля и 28 октября; налог за год – до 28 апреля следующего года','Декларацию за год ИП подаёт до 25 апреля.']]

FAQ=[
("Что выгоднее для ИП в 2026 году: УСН 6% или 15%?","Без сотрудников «Доходы» 6% обычно выгоднее, пока расходы меньше примерно "+pct(bes[1][1])+" дохода. Пример: доход 3 млн ₽ и расходы 1,5 млн ₽ – на 6% вы отдадите "+r(d[2])+", на 15% – "+r(d[5])+". Если расходы большие (например, 4,8 млн ₽ из 6 млн ₽), выгоднее 15%."),
("Сколько ИП платит страховых взносов за себя в 2026 году?","57 390 ₽ фиксированных до 28 декабря 2026 года. Если доход больше 300 000 ₽, ещё 1% с суммы сверх 300 000 ₽ до 1 июля 2027 года, но не больше 321 818 ₽. При доходе 3 млн ₽ это 57 390 + 27 000 = 84 390 ₽."),
("Можно ли уменьшить налог УСН 6% на страховые взносы?","Да. ИП без сотрудников уменьшает налог на всю сумму взносов, иногда до нуля. С сотрудниками налог можно уменьшить не больше чем наполовину. При доходе 1,2 млн ₽ без сотрудников: налог 72 000 ₽ − взносы 66 390 ₽ = 5 610 ₽."),
("Что такое минимальный налог на УСН 15%?","Это 1% от всех доходов. Его платят, если 15% от «доходы минус расходы» получилось меньше. Например, при доходе 5 млн ₽ и убытке минимальный налог – 50 000 ₽."),
("Платят ли ИП на УСН НДС в 2026 году?","Да, если доход больше 20 млн ₽. Можно выбрать специальную ставку 5% или 7% (без вычетов входящего НДС) или общую 22%. В 2027 году порог – 15 млн ₽, с 2028 года – 10 млн ₽."),
("Когда платить налог по УСН и подавать декларацию?","Авансы – до 28 апреля, 28 июля и 28 октября. Налог за 2026 год – до 28 апреля 2027 года, декларация – до 25 апреля 2027 года."),
("Почему на 6% сумма налога и взносов ровно 6% дохода?","Потому что взносы вычитаются из налога. Пока 6% дохода больше взносов, вы отдаёте ровно 6%: часть – взносами, остальное – налогом. При доходе 3 млн ₽ это 180 000 ₽."),
]

art='''<h2 id="figures">Главные цифры 2026 года</h2>
'''+table(['Что','Сколько','Что это значит'],fig)+'''
<h2 id="ex">Примеры: 6% или 15%</h2>
<div id="examples">'''+table(['Доходы за год','Расходы за год','УСН 6%: налог + взносы','УСН 15%: налог + взносы','Выгоднее'],rows)+'''</div>
<ul><li><b>Доход 1,2 млн ₽, расходы 400 тыс. ₽.</b> На 6% налог 72 000 ₽ почти целиком гасится взносами 66 390 ₽. Доплатить остаётся 5 610 ₽.</li>
<li><b>Доход 3 млн ₽, расходы 1,5 млн ₽.</b> 6% дают 180 000 ₽ всего, 15% – '''+r(d[5])+'''. Выгоднее 6%.</li>
<li><b>Доход 6 млн ₽, расходы 4,8 млн ₽.</b> Расходы – 80% дохода. Тут уже выгоднее 15%: '''+r(tot(6e6,4.8e6)[5])+''' против 360 000 ₽.</li>
<li><b>С сотрудниками</b> при доходе 1,2 млн ₽ налог 72 000 ₽ можно уменьшить только наполовину – до 36 000 ₽. Вместе с взносами ИП выйдет '''+r(emp[2])+'''. (Взносы за самих сотрудников тоже уменьшают налог, но калькулятор их не учитывает.)</li></ul>
<p class="note">Все суммы посчитаны формулой этого калькулятора: ИП без льгот, базовые ставки 6% и 15%, взносы за 2026 год. На 15% 1% взноса считаем с разницы доходов и расходов.</p>
<h2 id="how">Как считать: простыми словами</h2>
<p>Пример. Доход 3 000 000 ₽, расходы 1 500 000 ₽, сотрудников нет.</p>
<ul><li><b>Взносы ИП</b> (обязательные платежи на пенсию и медицину): 57 390 ₽ + 1% × (3 000 000 − 300 000) = 57 390 + 27 000 = <b>84 390 ₽</b>.</li>
<li><b>УСН 6%:</b> 3 000 000 × 6% = 180 000 ₽. Вычитаем взносы: 180 000 − 84 390 = 95 610 ₽ налога. Вместе с взносами – <b>180 000 ₽</b>.</li>
<li><b>УСН 15%:</b> из дохода вычитаем расходы и взносы, берём 15%. Получается '''+r(d[4])+''' налога и '''+r(d[5])+''' вместе с взносами.</li></ul>
<p><b>УСН</b> – упрощённая система налогообложения: один налог вместо нескольких. «Доходы» 6% – налог со всей выручки. «Доходы минус расходы» 15% – налог только с прибыли, но расходы нужно подтверждать документами.</p>
<h3>Простое правило</h3>
<p>Без сотрудников 15% становится выгоднее, когда расходы больше примерно '''+pct(bes[0][1])+''' дохода при доходе 3 млн ₽, '''+pct(bes[1][1])+''' – при 6 млн ₽ и '''+pct(bes[2][1])+''' – при 10 млн ₽. Посчитайте свои цифры в калькуляторе.</p>
<h2 id="tips">Советы и частые ошибки</h2>
<ul><li><b>Проверьте ставку своего региона.</b> Многие регионы снижают ставки УСН для отдельных видов деятельности.</li>
<li><b>Не забудьте 1% взноса.</b> Его платят до 1 июля следующего года, и он тоже уменьшает налог 6%.</li>
<li><b>Расходы на 15% нужно подтвердить.</b> Нужны чеки, договоры и акты. Без документов расход не учтут.</li>
<li><b>Следите за порогом НДС.</b> Если доход приближается к 20 млн ₽, заранее выберите ставку НДС.</li>
<li><b>Сменить объект можно только с нового года.</b> Обычно уведомление подают до 31 декабря.</li></ul>
<h2 id="faq" style="margin-top:22px">Частые вопросы</h2>'''+''.join(f'<h3>{q}</h3><p>{a}</p>' for q,a in FAQ)+'''
<p class="note">Источники (проверено 25 ноября 2026 г.): <a href="https://www.nalog.gov.ru/rn77/taxation/taxes/usn/" rel="nofollow">ФНС России – упрощённая система налогообложения</a>; <a href="https://www.nalog.gov.ru/rn77/taxation/insprem/" rel="nofollow">ФНС России – страховые взносы</a>; <a href="https://www.consultant.ru/document/cons_doc_LAW_28165/" rel="nofollow">Налоговый кодекс РФ, ст. 346.18, 346.20, 346.21, 430</a>; Федеральный закон от 28.11.2025 № 425-ФЗ. Расчёты сделаны формулой этого калькулятора. Это справочная информация, а не налоговая консультация.</p>'''

out=build(P,'Калькулятор УСН для ИП 2026 – 6% или 15%, налог и взносы',
 'Что выгоднее ИП в 2026 году: УСН 6% или 15%. Взносы 57 390 ₽ + 1%, минимальный налог, НДС от 20 млн ₽, примеры расчёта и сроки уплаты.',
 art,FAQ,form=form,calc=calc)
add_top(out,[('Автор','Hong Life Calculators'),('Проверено','25 ноября 2026 г.'),('Источники','ФНС России, Налоговый кодекс РФ')],
 [('form','Калькулятор'),('figures','Цифры 2026 года'),('ex','Примеры'),('how','Как считать'),('tips','Советы'),('faq','Частые вопросы')],'Содержание',('#examples','ru'))
